text:
.fm-root { position:absolute; inset:0 }
.fm-cam { position:absolute; inset:0; transform-origin:0 0 }
.fm-art { position:absolute; inset:0; width:100%; height:100% }
.fm-diagram { position:absolute; inset:0 }

/* the lifted draft, the finished turns */
.fm-lift { position:absolute; left:168px; top:722px; font-size:27px; line-height:34px; color:var(--ink); white-space:nowrap; opacity:0 }
.fm-slab { position:absolute; left:190px; width:420px; height:74px; border-radius:10px; background:var(--panel2); border:1px solid var(--line); box-shadow:0 16px 34px rgba(0,0,0,.3), inset 0 1px 0 color-mix(in srgb,var(--second) 7%,transparent); opacity:0 }
.fm-bar { position:absolute; left:22px; height:5px; border-radius:3px; background:color-mix(in srgb,var(--second) 16%,transparent) }
.fm-tag { position:absolute; right:20px; top:12px; font-family:ui-monospace,Menlo,monospace; font-size:16px; color:var(--ink3) }
.fm-lab { position:absolute; font-family:ui-monospace,Menlo,monospace; font-size:19px; color:var(--ink3); letter-spacing:.04em; opacity:0 }
.fm-lab-a { left:190px; top:352px }
.fm-lab-b { left:846px; top:336px; font-size:17px }

/* one panel, from read-only helper to the Depth dock */
.fm-plate { position:absolute; left:1000px; top:420px; width:740px; height:260px; border-radius:14px; overflow:hidden;
  background:var(--panel); border:1px solid color-mix(in srgb,var(--main) 38%,transparent);
  box-shadow:0 30px 70px rgba(0,0,0,.42), inset 0 1px 0 color-mix(in srgb,var(--main) 20%,transparent); opacity:0 }
.fm-plate-c { position:absolute; left:0; top:0; width:740px; height:260px; opacity:0 }
.fm-lock { position:absolute; left:26px; top:22px; width:20px; height:16px; border:2px solid var(--main); border-radius:3px }
.fm-lock:before { content:""; position:absolute; left:3px; top:-9px; width:8px; height:8px; border:2px solid var(--main); border-bottom:0; border-radius:6px 6px 0 0 }
.fm-ptitle { position:absolute; left:60px; top:12px; font-size:30px; font-weight:600; color:var(--ink) }
.fm-psub { position:absolute; right:26px; top:22px; font-family:ui-monospace,Menlo,monospace; font-size:17px; color:var(--ink3) }
.fm-kv { position:absolute; left:24px; top:66px; width:692px; height:44px; border-radius:9px; opacity:0;
  background:color-mix(in srgb,var(--main) 15%,transparent); border:1px solid color-mix(in srgb,var(--main) 40%,transparent);
  display:flex; align-items:center; gap:10px; padding:0 12px; font-family:ui-monospace,Menlo,monospace; font-size:19px; color:var(--ink) }
.fm-tick { width:6px; height:15px; border-radius:2px; background:var(--accent); opacity:.9 }
.fm-kvnote { margin-left:auto; color:var(--ink2); font-size:16px }
.fm-back { position:absolute; left:24px; top:200px; display:flex; align-items:center; gap:10px; opacity:0;
  font-family:ui-monospace,Menlo,monospace; font-size:18px; color:var(--ink2) }
.fm-backarrow { color:var(--main) }

/* the dock's own rows */
.fm-dock-c { position:absolute; left:0; top:0; right:0; height:177px; opacity:0 }
.fm-drow { position:absolute; left:18px; top:13px; display:flex; align-items:center; gap:12px }
.fm-badge { display:inline-flex; align-items:center; gap:7px; font-family:ui-monospace,Menlo,monospace; font-weight:600;
  font-size:16.5px; padding:3px 10px; border-radius:8px; background:color-mix(in srgb,var(--main) 44%,var(--ground)); color:var(--second); opacity:0 }
.fm-spin { width:15px; height:15px; border-radius:50%; border:2.5px solid color-mix(in srgb,var(--second) 26%,transparent); border-top-color:var(--second); display:block }
.fm-meter { display:inline-flex; gap:5px }
.fm-cell { width:12px; height:12px; border-radius:3px; background:color-mix(in srgb,var(--second) 15%,transparent) }
.fm-cell.on { background:var(--main) }
.fm-cell.done { background:var(--accent) }
.fm-stages { display:inline-flex; gap:6px; margin-left:4px }
.fm-stage { font-size:16.5px; padding:2px 11px; border-radius:999px; color:var(--ink2); opacity:.62 }
.fm-stage.on { color:var(--ink); font-weight:600; background:color-mix(in srgb,var(--second) 15%,transparent); opacity:1 }
.fm-stage.past { opacity:1 }
.fm-dright { position:absolute; right:18px; top:11px; display:flex; align-items:center; gap:11px; opacity:0 }
.fm-mchip { font-family:ui-monospace,Menlo,monospace; font-size:16.5px; padding:2px 10px; border-radius:999px; border:1px solid var(--line2); color:var(--ink2); white-space:nowrap }
.fm-esc { font-size:16.5px; padding:3px 11px; border-radius:8px; border:1px solid var(--line2); color:var(--ink) }
.fm-clock { font-family:ui-monospace,Menlo,monospace; font-size:16.5px; color:var(--ink2) }
.fm-draft { position:absolute; left:18px; top:48px; font-size:16.5px; color:var(--ink2); opacity:0; white-space:nowrap }
.fm-gen { position:absolute; right:18px; top:78px; font-family:ui-monospace,Menlo,monospace; font-size:16.5px; color:var(--ink); opacity:0 }
.fm-prev { position:absolute; left:18px; right:18px; top:116px; padding:9px 13px; border-radius:10px; border:1px solid transparent;
  background:color-mix(in srgb,var(--second) 7%,transparent); color:var(--ink2); font-size:16.5px; line-height:1.55; opacity:0 }

/* the tool row lives across both states */
.fm-tools { position:absolute; left:24px; top:128px }
.fm-g1, .fm-g2 { position:absolute; left:0; top:0; display:flex; align-items:center; gap:9px }
.fm-g2 { opacity:0 }
.fm-tool { display:inline-flex; align-items:center; gap:8px; padding:4px 12px; border-radius:999px; white-space:nowrap;
  border:1px solid color-mix(in srgb,var(--second) 16%,transparent); background:color-mix(in srgb,var(--second) 6%,transparent);
  font-family:ui-monospace,Menlo,monospace; font-size:17px; color:var(--ink2) }
.fm-tool i { width:8px; height:8px; border-radius:999px; background:var(--accent) }
.fm-tool.off { text-decoration:line-through; border-style:dashed; opacity:0 }
.fm-tool.off i { background:color-mix(in srgb,var(--second) 30%,transparent) }

/* composer bits on top */
.fm-run { position:relative; display:inline-flex; align-items:center }
.fm-restore { position:absolute; left:0; top:50%; transform:translateY(-50%); transform-origin:0 50%; opacity:0; background:transparent }
.fm-body { position:relative }
.fm-ph { position:absolute; left:0; top:0 }
.fm-typed { position:absolute; left:0; top:0 }
.fm-pl { position:absolute; left:0; top:0; opacity:0 }
.fm-l1, .fm-l2 { font-size:18px; line-height:1.55; white-space:pre-wrap }
.fm-cur { position:absolute; left:1226px; top:705px; opacity:0 }
.fm-ring { position:absolute; left:1226px; top:705px; width:60px; height:60px; margin:-30px 0 0 -30px;
  border:2px solid var(--main); border-radius:50%; opacity:0 }

/* the titles */
.fm-w1, .fm-w2, .fm-w3, .fm-w4 { left:150px; top:118px; opacity:0 }

/* the end card */
.fm-ec { position:absolute; left:0; top:0; width:1920px; text-align:center; opacity:0 }
.fm-mark { display:block; margin:0 auto 26px }
.fm-name { font-size:96px; line-height:1.08; font-weight:600; letter-spacing:-.015em; color:var(--ink) }
.fm-line { font-size:34px; line-height:1.4; color:color-mix(in srgb,var(--second) 78%,transparent); margin-top:14px }
.fm-by { font-family:ui-monospace,Menlo,monospace; font-size:19px; letter-spacing:.08em; color:var(--ink3); margin-top:22px }
